    10	// ContainsExpansion returns true if value contains
    11	// expansion syntax, e.g. $1 or ${10}
    12	func ContainsExpansion(val string) bool {
    13		return reExpansion.FindAllStringIndex(val, -1) != nil
    14	}
    15	
    16	// GlobToRegexp replaces glob-style standalone wildcard values
    17	// with real .* regexp-friendly values, does not modify regexp-compatible values,
    18	// quotes non-wildcard values
    19	func GlobToRegexp(in string) string {
    20		return replaceWildcard.ReplaceAllString(regexp.QuoteMeta(in), "(.*)")
    21	}
    22	
    23	// ReplaceRegexp replaces value in string, accepts regular expression and simplified
    24	// wildcard syntax, it has several important differeneces with standard lib
    25	// regexp replacer:
    26	// * Wildcard globs '*' are treated as regular expression .* expression
    27	// * Expression is treated as regular expression if it starts with ^ and ends with $
    28	// * Full match is expected, partial replacements ignored
    29	// * If there is no match, returns not found error
    30	func ReplaceRegexp(expression string, replaceWith string, input string) (string, error) {
    31		if !strings.HasPrefix(expression, "^") || !strings.HasSuffix(expression, "$") {
    32			// replace glob-style wildcards with regexp wildcards
    33			// for plain strings, and quote all characters that could
    34			// be interpreted in regular expression
    35			expression = "^" + GlobToRegexp(expression) + "$"
    36		}
    37		expr, err := regexp.Compile(expression)
    38		if err != nil {
    39			return "", trace.BadParameter(err.Error())
    40		}
    41		// if there is no match, return NotFound error
    42		index := expr.FindAllStringIndex(input, -1)
    43		if len(index) == 0 {
    44			return "", trace.NotFound("no match found")
    45		}
    46		return expr.ReplaceAllString(input, replaceWith), nil
    47	}
    48	
    49	// SliceMatchesRegex checks if input matches any of the expressions. The
    50	// match is always evaluated as a regex either an exact match or regexp.
    51	func SliceMatchesRegex(input string, expressions []string) (bool, error) {
    52		for _, expression := range expressions {
    53			if !strings.HasPrefix(expression, "^") || !strings.HasSuffix(expression, "$") {
    54				// replace glob-style wildcards with regexp wildcards
    55				// for plain strings, and quote all characters that could
    56				// be interpreted in regular expression
    57				expression = "^" + GlobToRegexp(expression) + "$"
    58			}
    59	
    60			expr, err := regexp.Compile(expression)
    61			if err != nil {
    62				return false, trace.BadParameter(err.Error())
    63			}
    64	
    65			// Since the expression is always surrounded by ^ and $ this is an exact
    66			// match for either a a plain string (for example ^hello$) or for a regexp
    67			// (for example ^hel*o$).
    68			if expr.MatchString(input) {
    69				return true, nil
    70			}
    71		}
    72	
    73		return false, nil
    74	}
    75	
    76	var replaceWildcard = regexp.MustCompile(`(\\\*)`)
    77	var reExpansion = regexp.MustCompile(`\$[^\$]+`)
		} else {
			c.Assert(err, check.FitsTypeOf, testCase.err, comment)
